<?php require '../config.php'; admin_only(); $msg=''; $dir=__DIR__.'/uploads/'; if(!is_dir($dir))mkdir($dir,0777,true);
if(isset($_POST['add'])) { $title=trim($_POST['title']);$date=$_POST['event_date'];$location=trim($_POST['location']);$poster='';
 if(isset($_FILES['poster']) && $_FILES['poster']['error']===UPLOAD_ERR_OK) { if($_FILES['poster']['size']>2*1024*1024) $msg='Image must be under 2 MB.'; else { $ext=strtolower(pathinfo($_FILES['poster']['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png']))$msg='Only JPG/PNG allowed.'; else { $poster=uniqid().'.'.$ext; move_uploaded_file($_FILES['poster']['tmp_name'],$dir.$poster); } } }
 if($msg==='') { $s=$conn->prepare('INSERT INTO events(title,category,event_date,location,poster) VALUES(?,?,?,?,?)');$cat='General';$s->bind_param('sssss',$title,$cat,$date,$location,$poster);$msg=$s->execute()?'Event added.':'Could not add event.'; } }
if(isset($_GET['delete'])) { $id=(int)$_GET['delete'];$s=$conn->prepare('DELETE FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$msg='Delete request completed.'; }
$rows=$conn->query('SELECT * FROM events ORDER BY id DESC');
?><h2>Practical 12: Event Management</h2><p><?=h($msg)?></p><form method="post" enctype="multipart/form-data"><input name="title" placeholder="Event title" required><input type="date" name="event_date" required><input name="location" placeholder="Location" required><input type="file" name="poster" accept=".jpg,.jpeg,.png"><button name="add">Add event</button></form><table border="1" cellpadding="6"><tr><th>Poster</th><th>Title</th><th>Date</th><th>Location</th><th>Action</th></tr><?php while($e=$rows->fetch_assoc()):?><tr><td><?php if($e['poster']) echo '<img width="70" src="uploads/'.h($e['poster']).'">';?></td><td><?=h($e['title'])?></td><td><?=h($e['event_date'])?></td><td><?=h($e['location'])?></td><td><a onclick="return confirm('Delete event?')" href="?delete=<?=$e['id']?>">Delete</a></td></tr><?php endwhile;?></table>